#!/usr/bin/env bash
# Strips TypeScript types into plain JavaScript under dist/ and writes the ./app launcher.
set -euo pipefail
cd "$(dirname "$0")"

rm -rf dist app
mkdir -p dist

node --input-type=module -e '
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";
for (const file of readdirSync("src").filter((f) => f.endsWith(".ts"))) {
  const js = stripTypeScriptTypes(readFileSync(`src/${file}`, "utf8"), { mode: "strip" })
    .replace(/from (["\x27])(\.[^"\x27]*)\.ts\1/g, "from $1$2.js$1");
  writeFileSync(`dist/${file.replace(/\.ts$/, ".js")}`, js);
}
writeFileSync("dist/package.json", JSON.stringify({ type: "module" }) + "\n");
' 2> >(grep -v ExperimentalWarning >&2 || true)

cat > app <<'LAUNCHER'
#!/usr/bin/env bash
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
exec node --disable-warning=ExperimentalWarning "$DIR/dist/main.js" "$@"
LAUNCHER
chmod +x app

/**
 * 64-bit signed integer expression evaluator.
 *
 * Grammar:
 *   expr    := term    (('+' | '-') term)*
 *   term    := unary   (('*' | '/' | '%') unary)*
 *   unary   := '-' unary | primary
 *   primary := NUMBER | '(' expr ')'
 *
 * Parsing uses an explicit operator stack (operator precedence parsing)
 * rather than recursion, so arbitrarily deep nesting cannot overflow the
 * call stack.
 */

const INT64_MIN = -(2n ** 63n);
const INT64_MAX = 2n ** 63n - 1n;

/** Raised for any syntax, division-by-zero or overflow failure. */
export class CalcError extends Error {
           reason                                            ;

  constructor(reason                     ) {
    super(`calc error: ${reason}`);
    this.name = 'CalcError';
    this.reason = reason;
  }
}


/** Entries on the operator stack: binary operators, unary negation, or an open parenthesis. */


const PRECEDENCE                                        = {
  '+': 1,
  '-': 1,
  '*': 2,
  '/': 2,
  '%': 2,
  neg: 3,
};

const CH_0 = 0x30;
const CH_9 = 0x39;
const CH_SPACE = 0x20;
const CH_TAB = 0x09;

function checked(value        )         {
  if (value < INT64_MIN || value > INT64_MAX) throw new CalcError('overflow');
  return value;
}

function applyBinary(op          , a        , b        )         {
  switch (op) {
    case '+':
      return checked(a + b);
    case '-':
      return checked(a - b);
    case '*':
      return checked(a * b);
    case '/':
      if (b === 0n) throw new CalcError('division-by-zero');
      // BigInt division truncates toward zero; MIN / -1 is caught by the range check.
      return checked(a / b);
    case '%':
      if (b === 0n) throw new CalcError('division-by-zero');
      // BigInt remainder follows the dividend's sign; MIN % -1 is 0.
      return a % b;
  }
}

function parseLiteral(digits        )         {
  const value = BigInt(digits);
  if (value > INT64_MAX) throw new CalcError('overflow');
  return value;
}

const isBlank = (c        )          => c === CH_SPACE || c === CH_TAB;
const isDigit = (c        )          => c >= CH_0 && c <= CH_9;

/** Evaluates one expression, throwing CalcError on failure. */
export function evaluate(line        )         {
  const values           = [];
  const ops            = [];

  const reduceTop = ()       => {
    const op = ops.pop();
    if (op === 'neg') {
      values.push(checked(-values.pop() ));
    } else if (op !== undefined && op !== '(') {
      const b = values.pop() ;
      const a = values.pop() ;
      values.push(applyBinary(op, a, b));
    }
  };

  // Reduces stacked operators that bind at least as tightly as `minPrecedence`.
  const reduceWhile = (minPrecedence        )       => {
    while (ops.length > 0) {
      const top = ops[ops.length - 1];
      if (top === '(' || PRECEDENCE[top] < minPrecedence) return;
      reduceTop();
    }
  };

  let expectOperand = true;
  const n = line.length;
  let i = 0;

  while (i < n) {
    const c = line.charCodeAt(i);
    if (isBlank(c)) {
      i++;
      continue;
    }
    const ch = line[i];

    if (expectOperand) {
      if (isDigit(c)) {
        let end = i + 1;
        while (end < n && isDigit(line.charCodeAt(end))) end++;
        values.push(parseLiteral(line.slice(i, end)));
        i = end;
        expectOperand = false;
        continue;
      }
      if (ch === '-') ops.push('neg');
      else if (ch === '(') ops.push('(');
      else throw new CalcError('syntax');
      i++;
      continue;
    }

    switch (ch) {
      case '+':
      case '-':
      case '*':
      case '/':
      case '%':
        reduceWhile(PRECEDENCE[ch]);
        ops.push(ch);
        expectOperand = true;
        break;
      case ')':
        reduceWhile(0);
        if (ops.pop() !== '(') throw new CalcError('syntax');
        break;
      default:
        throw new CalcError('syntax');
    }
    i++;
  }

  if (expectOperand) throw new CalcError('syntax');
  reduceWhile(0);
  if (ops.length > 0) throw new CalcError('syntax');
  return values[0];
}

function isBlankLine(line        )          {
  for (let i = 0; i < line.length; i++) {
    if (!isBlank(line.charCodeAt(i))) return false;
  }
  return true;
}

/** Returns the output for one input line, or null for a blank line. */
export function lineResult(line        )                {
  if (isBlankLine(line)) return null;
  try {
    return evaluate(line).toString();
  } catch (err) {
    if (err instanceof CalcError) return 'error';
    throw err;
  }
}

import { lineResult } from './calc.js';

const FLUSH_THRESHOLD = 1 << 16;

/** Reads stdin line by line (split on '\n' only) and writes one result per non-blank line. */
async function run()                {
  process.stdin.setEncoding('latin1');

  let pending = '';
  let out           = [];
  let outSize = 0;

  const flush = async ()                => {
    if (out.length === 0) return;
    const chunk = out.join('');
    out = [];
    outSize = 0;
    if (!process.stdout.write(chunk, 'latin1')) {
      await new Promise      ((resolve) => process.stdout.once('drain', resolve));
    }
  };

  const emit = (line        )       => {
    const result = lineResult(line);
    if (result === null) return;
    out.push(result, '\n');
    outSize += result.length + 1;
  };

  for await (const chunk of process.stdin                         ) {
    const data = pending + chunk;
    let start = 0;
    let nl        ;
    while ((nl = data.indexOf('\n', start)) !== -1) {
      emit(data.slice(start, nl));
      start = nl + 1;
    }
    pending = data.slice(start);
    if (outSize >= FLUSH_THRESHOLD) await flush();
  }
  if (pending.length > 0) emit(pending);
  await flush();
}

await run();
process.exitCode = 0;

/**
 * 64-bit signed integer expression evaluator.
 *
 * Grammar:
 *   expr    := term    (('+' | '-') term)*
 *   term    := unary   (('*' | '/' | '%') unary)*
 *   unary   := '-' unary | primary
 *   primary := NUMBER | '(' expr ')'
 *
 * Parsing uses an explicit operator stack (operator precedence parsing)
 * rather than recursion, so arbitrarily deep nesting cannot overflow the
 * call stack.
 */

const INT64_MIN = -(2n ** 63n);
const INT64_MAX = 2n ** 63n - 1n;

/** Raised for any syntax, division-by-zero or overflow failure. */
export class CalcError extends Error {
  readonly reason: 'syntax' | 'division-by-zero' | 'overflow';

  constructor(reason: CalcError['reason']) {
    super(`calc error: ${reason}`);
    this.name = 'CalcError';
    this.reason = reason;
  }
}

type BinaryOp = '+' | '-' | '*' | '/' | '%';
/** Entries on the operator stack: binary operators, unary negation, or an open parenthesis. */
type StackOp = BinaryOp | 'neg' | '(';

const PRECEDENCE: Record<Exclude<StackOp, '('>, number> = {
  '+': 1,
  '-': 1,
  '*': 2,
  '/': 2,
  '%': 2,
  neg: 3,
};

const CH_0 = 0x30;
const CH_9 = 0x39;
const CH_SPACE = 0x20;
const CH_TAB = 0x09;

function checked(value: bigint): bigint {
  if (value < INT64_MIN || value > INT64_MAX) throw new CalcError('overflow');
  return value;
}

function applyBinary(op: BinaryOp, a: bigint, b: bigint): bigint {
  switch (op) {
    case '+':
      return checked(a + b);
    case '-':
      return checked(a - b);
    case '*':
      return checked(a * b);
    case '/':
      if (b === 0n) throw new CalcError('division-by-zero');
      // BigInt division truncates toward zero; MIN / -1 is caught by the range check.
      return checked(a / b);
    case '%':
      if (b === 0n) throw new CalcError('division-by-zero');
      // BigInt remainder follows the dividend's sign; MIN % -1 is 0.
      return a % b;
  }
}

function parseLiteral(digits: string): bigint {
  const value = BigInt(digits);
  if (value > INT64_MAX) throw new CalcError('overflow');
  return value;
}

const isBlank = (c: number): boolean => c === CH_SPACE || c === CH_TAB;
const isDigit = (c: number): boolean => c >= CH_0 && c <= CH_9;

/** Evaluates one expression, throwing CalcError on failure. */
export function evaluate(line: string): bigint {
  const values: bigint[] = [];
  const ops: StackOp[] = [];

  const reduceTop = (): void => {
    const op = ops.pop();
    if (op === 'neg') {
      values.push(checked(-values.pop()!));
    } else if (op !== undefined && op !== '(') {
      const b = values.pop()!;
      const a = values.pop()!;
      values.push(applyBinary(op, a, b));
    }
  };

  // Reduces stacked operators that bind at least as tightly as `minPrecedence`.
  const reduceWhile = (minPrecedence: number): void => {
    while (ops.length > 0) {
      const top = ops[ops.length - 1];
      if (top === '(' || PRECEDENCE[top] < minPrecedence) return;
      reduceTop();
    }
  };

  let expectOperand = true;
  const n = line.length;
  let i = 0;

  while (i < n) {
    const c = line.charCodeAt(i);
    if (isBlank(c)) {
      i++;
      continue;
    }
    const ch = line[i];

    if (expectOperand) {
      if (isDigit(c)) {
        let end = i + 1;
        while (end < n && isDigit(line.charCodeAt(end))) end++;
        values.push(parseLiteral(line.slice(i, end)));
        i = end;
        expectOperand = false;
        continue;
      }
      if (ch === '-') ops.push('neg');
      else if (ch === '(') ops.push('(');
      else throw new CalcError('syntax');
      i++;
      continue;
    }

    switch (ch) {
      case '+':
      case '-':
      case '*':
      case '/':
      case '%':
        reduceWhile(PRECEDENCE[ch]);
        ops.push(ch);
        expectOperand = true;
        break;
      case ')':
        reduceWhile(0);
        if (ops.pop() !== '(') throw new CalcError('syntax');
        break;
      default:
        throw new CalcError('syntax');
    }
    i++;
  }

  if (expectOperand) throw new CalcError('syntax');
  reduceWhile(0);
  if (ops.length > 0) throw new CalcError('syntax');
  return values[0];
}

function isBlankLine(line: string): boolean {
  for (let i = 0; i < line.length; i++) {
    if (!isBlank(line.charCodeAt(i))) return false;
  }
  return true;
}

/** Returns the output for one input line, or null for a blank line. */
export function lineResult(line: string): string | null {
  if (isBlankLine(line)) return null;
  try {
    return evaluate(line).toString();
  } catch (err) {
    if (err instanceof CalcError) return 'error';
    throw err;
  }
}

import { lineResult } from './calc.ts';

const FLUSH_THRESHOLD = 1 << 16;

/** Reads stdin line by line (split on '\n' only) and writes one result per non-blank line. */
async function run(): Promise<void> {
  process.stdin.setEncoding('latin1');

  let pending = '';
  let out: string[] = [];
  let outSize = 0;

  const flush = async (): Promise<void> => {
    if (out.length === 0) return;
    const chunk = out.join('');
    out = [];
    outSize = 0;
    if (!process.stdout.write(chunk, 'latin1')) {
      await new Promise<void>((resolve) => process.stdout.once('drain', resolve));
    }
  };

  const emit = (line: string): void => {
    const result = lineResult(line);
    if (result === null) return;
    out.push(result, '\n');
    outSize += result.length + 1;
  };

  for await (const chunk of process.stdin as AsyncIterable<string>) {
    const data = pending + chunk;
    let start = 0;
    let nl: number;
    while ((nl = data.indexOf('\n', start)) !== -1) {
      emit(data.slice(start, nl));
      start = nl + 1;
    }
    pending = data.slice(start);
    if (outSize >= FLUSH_THRESHOLD) await flush();
  }
  if (pending.length > 0) emit(pending);
  await flush();
}

await run();
process.exitCode = 0;
